import{_ as t,c as o,o as r,ah as a}from"./chunks/framework.CsdM_DPq.js";const j=JSON.parse('{"title":"开始使用 Next.js","description":"","frontmatter":{},"headers":[],"relativePath":"column/Nextjs/001_start.md","filePath":"column/Nextjs/001_start.md","lastUpdated":1767777031000}'),l={name:"column/Nextjs/001_start.md"};function s(c,e,d,n,i,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="开始使用-next-js" tabindex="-1">开始使用 Next.js <a class="header-anchor" href="#开始使用-next-js" aria-label="Permalink to “开始使用 Next.js”">​</a></h1><blockquote><p>欢迎来到 Next.js 学习之旅！本教程将带你从零开始创建你的第一个 Next.js 应用。</p></blockquote><h2 id="什么是-next-js" tabindex="-1">什么是 Next.js？ <a class="header-anchor" href="#什么是-next-js" aria-label="Permalink to “什么是 Next.js？”">​</a></h2><p><code>Next.js</code> 是一个基于 <code>React</code> 全栈框架，由 <code>Vercel</code> 开发和维护，那么它有什么优势呢？ 官网地址: <a href="https://nextjs.org/" target="_blank" rel="noreferrer">https://nextjs.org/</a> 中文网站：<a href="https://nextjscn.org/" target="_blank" rel="noreferrer">https://nextjscn.org/</a></p><ul><li><strong>SSR</strong>：服务端渲染，可以提高页面加载速度</li><li><strong>SSG</strong>：静态站点生成，可以生成静态页面，类似于 <code>Vitepress / Astro</code> 等静态站点生成工具</li><li><strong>SEO</strong>: <code>Next.js</code> 提供了 <code>SEO</code> 优化，让你的网站更容易被搜索引擎收录</li><li><strong>AI</strong>: <code>Vercel</code> 提供了 <code>AI SDK</code> 可以跟 <code>Next.js</code> 轻松结合，让你可以轻松实现 <code>AI</code> 应用</li><li><strong>服务端操作</strong>: <code>Next.js</code> 提供了服务端操作，顺便学习服务端知识，为以后做全栈开发打下基础</li><li><strong>社区丰富</strong>: <code>Next.js</code> 拥有庞大的社区，可以让你轻松找到解决方案</li><li><strong>部署</strong>: 支持多种部署选项，与 <code>Vercel</code> 等平台集成良好，可以快速部署</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在学习 <code>Next.js</code> 之前，你需要掌握以下知识：</p><ul><li>HTML <code>熟练使用</code></li><li>CSS <code>熟练使用</code></li><li>JavaScript <code>熟练使用</code></li><li>TypeScript <code>基本使用即可</code></li><li>React <code>熟练使用</code></li><li>Node.js <code>基本使用即可</code></li></ul><h2 id="next-js-市场情况" tabindex="-1">Next.js 市场情况 <a class="header-anchor" href="#next-js-市场情况" aria-label="Permalink to “Next.js 市场情况”">​</a></h2><p>截止：2025 年 11 月 11 日，npm 下载量</p><ul><li>Next.js: <code>13,294,097</code></li><li>Nuxt.js: <code>956,540</code></li><li>Astro: <code>747,707</code></li><li>SvelteKit: <code>626,494</code></li></ul><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to “环境准备”">​</a></h2><ul><li><code>Node.js</code> 环境 下载地址:<a href="https://nodejs.org/en/download" target="_blank" rel="noreferrer">https://nodejs.org/en/download</a> 注：最低版本要求 <code>20.9</code></li><li>使用 <code>nvm</code>(Node Version Manager) 下载地址:<a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">https://github.com/nvm-sh/nvm</a> (推荐)</li><li>Visual Studio Code，WebStorm 等</li></ul>',13)])])}const p=t(l,[["render",s]]);export{j as __pageData,p as default};
